create table public.game_mission_catalog(id integer primary key,data jsonb not null);
create table public.achievement_catalog(id integer primary key,data jsonb not null);
alter table public.game_mission_catalog enable row level security;
alter table public.achievement_catalog enable row level security;
revoke all on public.game_mission_catalog,public.achievement_catalog from anon,authenticated;
grant select on public.game_mission_catalog,public.achievement_catalog to authenticated;
create policy game_mission_catalog_read on public.game_mission_catalog for select to authenticated using(true);
create policy achievement_catalog_read on public.achievement_catalog for select to authenticated using(true);
